/*
 * Lump built-in ML model — browser runtime.
 *
 * Bit-for-bit port of src/lump/ml/features.py (normalisation, n-grams, CRC-32
 * hashing) plus the model scorer in src/lump/ml/model.py. It loads the
 * exact same model file the Python engine ships, so a prompt gets the same
 * probability in the browser as at the gateway. Parity is pinned by
 * extension/test/ml.test.js against fixtures generated by the Python side.
 */

const LumpML = (() => {
  const INVISIBLE_RE = /[\u200b\u200c\u200d\u2060\u2061\u2062\u2063\u2064\ufeff\u180e\u00ad\u202a\u202b\u202c\u202d\u202e\u2066\u2067\u2068\u2069\u200e\u200f]/g;
  const TAGS_VS_RE = /[\u{E0000}-\u{E007F}\ufe00-\ufe0f\u{E0100}-\u{E01EF}]/gu;
  // With the u flag this matches only *unpaired* surrogates.
  const SURROGATE_RE = /[\uD800-\uDFFF]/gu;
  const WS_RE = /[\t\n\x0b\x0c\r \x1c-\x1f\x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+/g;
  const WORD_RE = /[a-z0-9]+/g;
  const ENC = new TextEncoder();

  const CRC_TABLE = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      t[n] = c >>> 0;
    }
    return t;
  })();

  // Same semantics as Python's zlib.crc32(data, seed).
  function crc32(bytes, seed = 0) {
    let c = (seed ^ 0xffffffff) >>> 0;
    for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  }

  function normalize(text, digitsToZero = true) {
    let t = String(text).replace(SURROGATE_RE, "�");
    t = t.normalize("NFKC").replace(INVISIBLE_RE, "").replace(TAGS_VS_RE, "").toLowerCase();
    if (digitsToZero) t = t.replace(/[0-9]/g, "0");
    return t.replace(WS_RE, " ").replace(/^ +| +$/g, "");
  }

  function ngrams(norm, cfg) {
    const out = [];
    const words = norm.match(WORD_RE) || [];
    for (const n of cfg.word_ngrams) {
      for (let i = 0; i + n <= words.length; i++) out.push("w:" + words.slice(i, i + n).join(" "));
    }
    const chars = Array.from(" " + norm + " ");
    for (const n of cfg.char_ngrams) {
      for (let i = 0; i + n <= chars.length; i++) {
        const gram = chars.slice(i, i + n).join("");
        if (gram.replace(/ /g, "") !== "") out.push("c:" + gram);
      }
    }
    return out;
  }

  function hashFeatures(grams, cfg) {
    const mask = (1 << cfg.hash_bits) - 1;
    const vec = new Map();
    for (const g of grams) {
      const h = crc32(ENC.encode(g));
      const idx = h & mask;
      const sign = cfg.signed_hash && (h >>> 31) ? -1 : 1;
      vec.set(idx, (vec.get(idx) || 0) + sign);
    }
    let sq = 0;
    for (const [idx, v] of vec) {
      const w = v ? Math.sign(v) * (1 + Math.log(Math.abs(v))) : 0;
      vec.set(idx, w);
      sq += w * w;
    }
    const norm = Math.sqrt(sq);
    if (norm > 0) for (const [idx, v] of vec) vec.set(idx, v / norm);
    return vec;
  }

  function windows(norm, cfg) {
    const chars = Array.from(norm);
    if (chars.length <= cfg.max_chars) return [norm];
    const out = [];
    for (let start = 0; start < chars.length; start += cfg.window_stride) {
      out.push(chars.slice(start, start + cfg.max_chars).join(""));
      if (start + cfg.max_chars >= chars.length) break;
    }
    return out;
  }

  function featurize(text, cfg) {
    const norm = normalize(text, cfg.digits_to_zero);
    return windows(norm, cfg).map((w) => hashFeatures(ngrams(w, cfg), cfg));
  }

  // --- model file (same bytes as src/lump/data/models/*.lumpml) ---
  const MAGIC = [0x4c, 0x55, 0x4d, 0x50, 0x4d, 0x4c, 0x01, 0x00]; // "LUMPML" 1.0

  async function sha256Hex(bytes) {
    const subtle = (typeof crypto !== "undefined" && crypto.subtle) ||
      (typeof require === "function" ? require("node:crypto").webcrypto.subtle : null);
    const digest = await subtle.digest("SHA-256", bytes);
    return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, "0")).join("");
  }

  async function loadModel(buffer) {
    const bytes = new Uint8Array(buffer);
    for (let i = 0; i < MAGIC.length; i++) if (bytes[i] !== MAGIC[i]) throw new Error("not a Lump model file");
    const hlen = new DataView(bytes.buffer, bytes.byteOffset).getUint32(8, true);
    const header = JSON.parse(new TextDecoder().decode(bytes.subarray(12, 12 + hlen)));
    const blob = bytes.subarray(12 + hlen);
    const C = header.classes.length;
    const D = 2 ** header.features.hash_bits;
    if (blob.length !== D * C) throw new Error("weight block has the wrong size");
    if ((await sha256Hex(blob)) !== header.weights_sha256) throw new Error("model checksum mismatch");
    return makeModel(header, new Int8Array(blob.buffer, blob.byteOffset, blob.length));
  }

  function makeModel(header, q) {
    const cfg = header.features;
    const C = header.classes.length;
    const scales = header.quant.scales;
    const bias = header.bias;
    const T = header.temperature || 1;
    const benign = header.classes.indexOf("benign");

    function probs(vec) {
      const z = new Float64Array(C);
      for (const [i, v] of vec) {
        const o = i * C;
        for (let c = 0; c < C; c++) z[c] += q[o + c] * v;
      }
      let m = -Infinity;
      for (let c = 0; c < C; c++) { z[c] = z[c] * scales[c] + bias[c]; if (z[c] > m) m = z[c]; }
      let sum = 0;
      const e = new Float64Array(C);
      for (let c = 0; c < C; c++) { e[c] = Math.exp((z[c] - m) / T); sum += e[c]; }
      for (let c = 0; c < C; c++) e[c] /= sum;
      return e;
    }

    function explain(text, window = 0, topK = 6) {
      const norm = normalize(text, cfg.digits_to_zero);
      const wins = windows(norm, cfg);
      const grams = ngrams(wins[Math.min(window, wins.length - 1)], cfg);
      const mask = (1 << cfg.hash_bits) - 1;
      const contrib = new Map();
      for (const g of grams) {
        const h = crc32(ENC.encode(g));
        const o = (h & mask) * C;
        const sign = cfg.signed_hash && (h >>> 31) ? -1 : 1;
        let attack = -Infinity;
        for (let c = 0; c < C; c++) if (c !== benign) attack = Math.max(attack, q[o + c] * scales[c]);
        contrib.set(g, (contrib.get(g) || 0) + sign * (attack - q[o + benign] * scales[benign]));
      }
      const ranked = [...contrib.entries()].filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]);
      const words = ranked.filter(([g]) => g.startsWith("w:")).map(([g, v]) => [g.slice(2), +v.toFixed(4)]);
      const chars = ranked.filter(([g]) => g.startsWith("c:")).map(([g, v]) => [g.slice(2).trim(), +v.toFixed(4)]);
      return words.concat(chars).slice(0, topK);
    }

    function score(text, opts = {}) {
      const vecs = featurize(text, cfg);
      let best = -1, bestP = null, bestW = 0;
      vecs.forEach((vec, w) => {
        const p = probs(vec);
        const pa = 1 - p[benign];
        if (pa > best) { best = pa; bestP = p; bestW = w; }
      });
      const out = { p_attack: best, probs: {}, window: bestW, windows: vecs.length };
      header.classes.forEach((c, i) => { out.probs[c] = bestP[i]; });
      out.label = header.classes[bestP.indexOf(Math.max(...bestP))];
      if (opts.explain) out.explanation = explain(text, bestW);
      return out;
    }

    return { header, thresholds: header.thresholds, score, explain, name: header.name, version: header.version };
  }

  return { crc32, normalize, ngrams, hashFeatures, windows, featurize, loadModel };
})();

if (typeof module !== "undefined" && module.exports) module.exports = LumpML;
if (typeof self !== "undefined") self.LumpML = LumpML;
